import { writeCanonicalJson, writeCanonicalText } from "@govlab/canonical-write";

await writeCanonicalJson(resolve(outDir, "catalog.generated.json"), { rules, summary });
await writeCanonicalText(resolve(outDir, "INDEX.generated.md"), renderedMarkdown);

await writeCanonicalJson(path, value);

const fresh = await renderCanonical(value);
if (readFileSync(path, "utf8") !== fresh) {
    throw new Error(`${path} has drifted — regenerate it`);
}
